use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let values = input.as_array().unwrap();
    let size = input.as_u64().unwrap();
    let mut result = Vec::new();

    for i in 0..values.len() {
        let chunk = values[i..i + size].iter().cloned().collect();
        result.push(serde_json::Value::Array(chunk));
    }

    Value::Array(result)
}
